"""ENGINEERING STAND-IN: writes protocol fixtures; imports no MACS2 libraries.

This is not a peak caller, model fit or scientific numerical oracle. Its exact
bytes are selected as a fake runtime only by the separate engineering tests.
"""
import sys
from pathlib import Path


def main(arguments):
    assert arguments[0] == 'callpeak'
    def selected(flag):
        return arguments[arguments.index(flag) + 1]
    treatment, control = selected('-t'), selected('-c')
    prefix, output = selected('-n'), Path(selected('--outdir'))
    counts = [len(Path(path).read_bytes().splitlines()) for path in (treatment, control)]
    name = prefix + '_peak_1'
    xls = (
        '# ENGINEERING STAND-IN; no MACS2 algorithm or native model was executed.\n'
        '# This file is generated by MACS version 2.2.9.1\n'
        '# format = AUTO\n'
        f'# ChIP-seq file = {[treatment]!r}\n'
        f'# control file = {[control]!r}\n'
        '# Broad region calling is off\n# Paired-End mode is off\n'
        f'# total tags in treatment: {counts[0]}\n'
        f'# tags after filtering in treatment: {counts[0]}\n'
        f'# total tags in control: {counts[1]}\n'
        f'# tags after filtering in control: {counts[1]}\n'
        '# d = 199\n'
        'chr\tstart\tend\tlength\tabs_summit\tpileup\t-log10(pvalue)\tfold_enrichment\t-log10(qvalue)\tname\n'
        f'chrSynthetic\t2\t3\t2\t3\t1\t1\t1\t1\t{name}\n'
    )
    (output / (prefix + '_peaks.xls')).write_text(xls)
    (output / (prefix + '_peaks.narrowPeak')).write_text(
        f'chrSynthetic\t1\t3\t{name}\t10\t.\t1\t1\t1\t1\n')
    (output / (prefix + '_summits.bed')).write_text(f'chrSynthetic\t2\t3\t{name}\t1\n')
    (output / (prefix + '_model.r')).write_text('# ENGINEERED CONTROL; this is not a native model fit.\n')
    print('ENGINEERING STAND-IN completed one protocol command; no MACS2 library was imported.')
    return 0


if __name__ == '__main__':
    raise SystemExit(main(sys.argv[1:]))
